mapper.select:
SELECT id, user_id, phone_number, birth_date, address_line1, marketing_opt_in, created_at
FROM user_profiles
WHERE user_id = #{userId}

mapper.update:
UPDATE user_profiles
SET phone_number     = #{phoneNumber},
    birth_date       = #{birthDate},
    address_line1    = #{addressLine1},
    marketing_opt_in = #{marketingOptIn}
WHERE user_id = #{userId}

mapper.select:

SELECT up.user_id, up.birth_date, u.name
FROM user_profiles up
         JOIN users u ON u.id = up.user_id
WHERE up.birth_date  >=  #{startDate}
  AND up.birth_date  <=  #{endDate}
  AND u.name LIKE #{namePattern}
